fn main() {
    for word in ["hello", "héllo", "Zoë", "日本", "hi🦉"] {
        let mut bytes = Vec::new();
        for b in word.bytes() {
            bytes.push(b.to_string());
        }
        let mut starts = Vec::new();
        for (i, _c) in word.char_indices() {
            starts.push(i.to_string());
        }
        println!("{word}|{}|{}|{}|{}", word.len(), word.chars().count(), bytes.join(" "), starts.join(" "));
    }
}

safe_slice.rs.src:
fn first_letters(s: &str, n: usize) -> &str {
    let mut seen = 0;
    for (i, _c) in s.char_indices() {
        if seen == n {
            return &s[..i];
        }
        seen += 1;
    }
    s
}

fn main() {
    let name = "Zoë Lee";
    println!("{} {}", name.is_char_boundary(3), name.is_char_boundary(4));
    println!("{}", first_letters(name, 3));
    println!("{}", first_letters("日本語", 2));
    println!("{}", first_letters("hi", 5));
}

